#!/bin/sh
# Writes test/fixtures/test-chain.ts: a throwaway certificate chain shaped like
# the App Store's (P-384 root and intermediate, P-256 leaf, Apple's role marker
# extensions), plus variants that each lack one thing a real chain has.
#
# The tests need a chain whose leaf key they hold, so they can sign payloads;
# Apple's real leaf keys are not available to anyone. OpenSSL writes these, so
# the DER reader is tested against an encoder other than its own. Re-running
# makes new keys, which is fine: nothing outside the tests trusts them.
#
# Needs OpenSSL 3.4 or later, for -not_before and -not_after, which keep the
# validity window fixed instead of relative to the day the script ran.
set -eu

here=$(cd "$(dirname "$0")" && pwd)
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
cd "$work"

not_before=20260101000000Z
not_after=20460101000000Z
org="app-store-jws test fixture"

cat >ext.cnf <<'EOF'
[req]
distinguished_name = dn
[dn]
[root]
basicConstraints = critical, CA:TRUE
keyUsage = critical, keyCertSign, cRLSign
[intermediate]
basicConstraints = critical, CA:TRUE, pathlen:0
keyUsage = critical, keyCertSign, cRLSign
1.2.840.113635.100.6.2.1 = ASN1:NULL
[intermediate_no_marker]
basicConstraints = critical, CA:TRUE, pathlen:0
keyUsage = critical, keyCertSign, cRLSign
[intermediate_not_ca]
basicConstraints = critical, CA:FALSE
1.2.840.113635.100.6.2.1 = ASN1:NULL
[leaf]
basicConstraints = critical, CA:FALSE
keyUsage = critical, digitalSignature
1.2.840.113635.100.6.11.1 = ASN1:NULL
[leaf_no_marker]
basicConstraints = critical, CA:FALSE
keyUsage = critical, digitalSignature
EOF

openssl ecparam -name secp384r1 -genkey -noout -out root.key
openssl ecparam -name secp384r1 -genkey -noout -out intermediate.key
openssl ecparam -name prime256v1 -genkey -noout -out leaf.key

# sign <name> <subject CN> <subject key> <issuer cert> <issuer key> <section>
sign() {
  openssl req -new -key "$3" -subj "/CN=$2/O=$org" -out "$1.csr"
  openssl x509 -req -in "$1.csr" -CA "$4" -CAkey "$5" -set_serial "0x$(openssl rand -hex 8)" \
    -sha384 -not_before "$not_before" -not_after "$not_after" \
    -extfile ext.cnf -extensions "$6" -outform DER -out "$1.der"
}

openssl req -new -x509 -key root.key -subj "/CN=Test Root/O=$org" -sha384 \
  -not_before "$not_before" -not_after "$not_after" \
  -config ext.cnf -extensions root -out root.pem
openssl x509 -in root.pem -outform DER -out root.der

sign intermediate "Test Intermediate" intermediate.key root.pem root.key intermediate
sign intermediate_no_marker "Test Intermediate" intermediate.key root.pem root.key intermediate_no_marker
sign intermediate_not_ca "Test Intermediate" intermediate.key root.pem root.key intermediate_not_ca
openssl x509 -in intermediate.der -inform DER -out intermediate.pem
sign leaf "Test Leaf" leaf.key intermediate.pem intermediate.key leaf
sign leaf_no_marker "Test Leaf" leaf.key intermediate.pem intermediate.key leaf_no_marker

openssl pkcs8 -topk8 -nocrypt -in leaf.key -outform DER -out leaf.pkcs8

# Base64 of a binary file on one line, portable across BSD and GNU base64.
b64() { openssl base64 -A -in "$1"; }

{
  echo "// Generated by test/fixtures/make-test-chain.sh; edit that, not this."
  echo "// A throwaway chain for the tests alone: nothing else trusts it."
  echo ""
  for name in root intermediate intermediate_no_marker intermediate_not_ca leaf leaf_no_marker; do
    printf 'export const %s = "%s";\n' "$name" "$(b64 "$name.der")"
  done
  printf 'export const leaf_key_pkcs8 = "%s";\n' "$(b64 leaf.pkcs8)"
} >"$here/test-chain.ts"
